-- Datos preservados. Ejecutar después de schema.sql; no reemplaza IDs existentes.
begin;
select setval(pg_get_serial_sequence('public.projects','id'), greatest(coalesce((select max(id) from public.projects),0),1), (select count(*) > 0 from public.projects));
select setval(pg_get_serial_sequence('public.skills','id'), greatest(coalesce((select max(id) from public.skills),0),1), (select count(*) > 0 from public.skills));
select setval(pg_get_serial_sequence('public.experiences','id'), greatest(coalesce((select max(id) from public.experiences),0),1), (select count(*) > 0 from public.experiences));
select setval(pg_get_serial_sequence('public.education','id'), greatest(coalesce((select max(id) from public.education),0),1), (select count(*) > 0 from public.education));
select setval(pg_get_serial_sequence('public.social_links','id'), greatest(coalesce((select max(id) from public.social_links),0),1), (select count(*) > 0 from public.social_links));
select setval(pg_get_serial_sequence('public.soft_skills','id'), greatest(coalesce((select max(id) from public.soft_skills),0),1), (select count(*) > 0 from public.soft_skills));
commit;
