insert into public.profile (id,name,role,description,tagline,location,avatar,cv,phone,show_phone) values (1,'Silvia Agustina Banegas','Estudiante de Informática / Desarrolladora Web','Soy estudiante de informática, interesada en el desarrollo web, los sistemas y la creación de soluciones tecnológicas. Me gusta aprender nuevas herramientas, resolver problemas y participar en proyectos donde pueda combinar programación, diseño y organización.','Aprendiendo, creando y desarrollando una idea a la vez.','Mar del Plata, Buenos Aires, Argentina.','','','',false) on conflict(id) do nothing;
insert into public.projects (id,title,description,full_description,image,category,date,status,github,demo,is_featured,display_order,technologies) values (1,'Portfolio personal Windows XP','Portfolio de una sola página con ventanas interactivas y contenido gestionado en Supabase.','Aplicación React con escritorio Windows XP, ventanas arrastrables y minimizables, filtros de proyectos y panel administrador. La persistencia está preparada para Supabase PostgreSQL, Auth y Storage; pendiente de conectar el proyecto en la nube.','','Full Stack','','En desarrollo','','',true,0,ARRAY['React','TypeScript','CSS','Supabase','Vite']::text[]) on conflict(id) do nothing;
